extends SceneTree
func _initialize() -> void:
	call_deferred("_run")
func _run() -> void:
	await process_frame
	var ps: PackedScene = load("res://previews/footstep_scuff_preview.tscn")
	print("preview loads: ", ps != null)
	var n: Node = ps.instantiate()
	print("preview root: ", n.name, "  class: ", n.get_class(), "  children=", n.get_child_count())
	for c in n.get_children():
		print("  - ", c.name, "  ", c.get_class())
	root.add_child(n)
	# Run enough frames for both trigger points to fire (frame 21+).
	for i in 30:
		await process_frame
	var scuff_count := 0
	for c in n.get_children():
		if c.name == "FootstepScuff":
			scuff_count += 1
			for cc in c.get_children():
				var cp: CPUParticles3D = cc
				print("    %s.emitting=%s" % [cc.name, cp.emitting])
	print("spawned FootstepScuff instances after 30 frames: ", scuff_count)
	quit(0)

